// src/components/ProductCard.js
import React from "react";
import { Link } from "react-router-dom";

// Component này nhận một đối tượng sản phẩm qua props
function ProductCard({ product }) {
  // Đảm bảo dữ liệu sản phẩm có sẵn
  if (!product) return null; 

  return (
    <div className="product-item">
      <div className="inner-image">
        {/* Liên kết đến trang chi tiết sản phẩm dựa trên ID */}
        <Link to={`/products/${product.id}`}>
          <img src={product.image} alt={product.name} />
        </Link>
      </div>
      <div className="inner-content">
        <h3 className="inner-title">
          <Link to={`/products/${product.id}`}>{product.name}</Link>
        </h3>
        {/* Đảm bảo giá được hiển thị đúng định dạng (VNĐ/đơn vị) */}
        <div className="inner-price">{product.price} VNĐ</div>
      </div>
    </div>
  );
}

export default ProductCard;
